package br.com.equilibra.transaction.application;
import br.com.equilibra.shared.api.CurrentUser;import br.com.equilibra.transaction.api.*;import br.com.equilibra.transaction.domain.*;import br.com.equilibra.transaction.infrastructure.FinancialTransactionRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;
@Service public class TransactionHistoryService{private final FinancialTransactionRepository repository;private final CurrentUser current;public TransactionHistoryService(FinancialTransactionRepository repository,CurrentUser current){this.repository=repository;this.current=current;}@Transactional(readOnly=true)public TransactionHistoryPageResponse list(int page,int size,TransactionType type,TransactionStatus status,Instant from,Instant to){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination parameters.");if(from!=null&&to!=null&&!from.isBefore(to))throw new IllegalArgumentException("from must be before to");Page<FinancialTransaction> result=repository.findHistory(current.id().toString(),type,status,from,to,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"occurredAt").and(Sort.by(Sort.Direction.DESC,"id"))));return new TransactionHistoryPageResponse(result.getContent().stream().map(TransactionHistoryResponse::from).toList(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages());}}
